INSERT INTO plagas (nombre_comun, nombre_cientifico, cultivo) VALUES ('Gusano cogollero','Spodoptera frugiperda','maiz')
INSERT INTO conocimiento_plaga (plaga_id, seccion, contenido, fuente_url) VALUES
(@pid, 'Qué es el gusano cogollero y cómo se llama', 'El gusano cogollero (Spodoptera frugiperda), también llamado oruga militar tardía, es la larva de una polilla. Es polífago: ataca varios cultivos, sobre todo gramíneas como maíz y sorgo, y puede estar presente durante todo el ciclo del cultivo.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Cuándo ataca al maíz', 'Puede atacar el maíz desde la germinación hasta la madurez. Según CropLife, los ataques más severos ocurren en la fase vegetativa inicial, hacia los 30 días después de la siembra, y las pérdidas de rendimiento citadas van del 30 al 64 %.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Qué daños causa en las hojas y el cogollo', 'La larva come hojas y brotes tiernos, sobre todo el cogollo. Hasta unas 4 hojas el daño es fuerte pero la planta suele sobrevivir; entre la 4.ª y la 6.ª hoja puede alimentarse del punto de crecimiento y matarla. Los ataques tardíos pueden dañar la espiga.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Escala de daño grados 1, 2 y 3', 'Grado 1: ventanitas, manchas translúcidas en las hojas sin perforarlas. Grado 2: defoliación moderada y primeras señales de aserrín. Grado 3: daño intenso en el cogollo, larvas grandes escondidas y mucho aserrín.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Cuándo controlar el gusano cogollero', 'El mejor momento para controlar es el daño grado 1, porque la larva aún está expuesta. Para detectarlo hay que recorrer el cultivo una vez por semana. En grado 3 la larva ya está dentro del cogollo y el control es difícil e incluso irreversible.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Cómo identificar a la polilla adulta', 'La polilla mide unos 35 a 40 mm con las alas abiertas. Las alas delanteras son oscuras con manchas blancas y las traseras son blancas o transparentes. Es poco atraída por la luz y los adultos pueden migrar.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Cómo identificar los huevos', 'La hembra pone masas de unos 100 a 300 huevos cubiertas por pelos de su abdomen, y en total pueden ser más de mil. Los huevos son semiesféricos, de unos 0,5 mm, verdosos al inicio y luego castaños. Se buscan en el envés de las hojas.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Cómo identificar la larva', 'Al nacer es verde clara; después se oscurece y muestra tres líneas claras a lo largo del cuerpo y una Y invertida clara en la cabeza. Llega a medir de 35 a 40 mm, es caníbal (por eso suele haber una sola larva por cogollo) y desarrolla en 6 estadios.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Duración del ciclo de vida y de cada etapa', 'La etapa de larva dura entre 14 y 25 días según temperatura y alimento. La pupa se forma en el suelo y dura de 7 a 13 días. El ciclo completo, de huevo a adulto, dura aproximadamente entre 24 y 40 días.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Umbral de daño para decidir el control', 'CropLife indica que el umbral económico va de 10 a 50 % de plantas infestadas según la etapa del cultivo, y cita recomendaciones de control desde cerca del 10 % hasta el 25 % de plantas atacadas, según el país y el estado de la planta.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero'),
(@pid, 'Monitoreo y manejo de la plaga', 'La mejor herramienta es el monitoreo y decidir según el nivel de daño. La mayoría de los fracasos se deben a actuar tarde, cuando la larva ya está dentro del cogollo. Usa solo productos registrados ante el ICA y con orientación de un técnico agrícola.', 'CropLife Latin America (resumen propio): https://croplifela.org/es/plagas/listado-de-plagas/gusano-cogollero');
